class Solution {
    public int balancedStringSplit(String s) {
        int balance = 0;
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            balance += s.charAt(i) == 'R' ? 1 : -1;
            if (balance == 0) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int balancedStringSplit(String s) {
        int r = 0;
        int l = 0;
        int pieces = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 'R') {
                r++;
            } else {
                l++;
            }
            if (r == l) {
                pieces++;
                r = 0;
                l = 0;
            }
        }
        return pieces;
    }
}

import java.util.*;

class Solution {
    public int balancedStringSplit(String s) {
        List<Integer> cuts = new ArrayList<>();
        int balance = 0;
        for (int i = 0; i < s.length(); i++) {
            balance += s.charAt(i) == 'R' ? 1 : -1;
            if (balance == 0) {
                cuts.add(i);
            }
        }
        return cuts.size();
    }
}

import java.util.*;

class Solution {
    public int balancedStringSplit(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        int pieces = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (stack.isEmpty() || stack.peek() == c) {
                stack.push(c);
            } else {
                stack.pop();
            }
            if (stack.isEmpty()) {
                pieces++;
            }
        }
        return pieces;
    }
}
